    'Tritanopia' => 'Tritanopie',
    'Turn on email or Slack notifications above before sending a test.' => 'Activez les notifications e-mail ou Slack ci-dessus avant d’envoyer un test.',
    'UI Components' => 'Composants d\'interface',
    'Understanding' => 'Comprendre',
    'Undo last revision' => 'Annuler la dernière version',
    'Unknown' => 'Inconnu',
    'Unknown criterion.' => 'Critère inconnu.',
    'Unknown site.' => 'Site inconnu.',
    'Unknown verdict.' => 'Verdict inconnu.',
    'Up {n, plural, =1{# point} other{# points}}' => 'Plus {n, plural, =1{# point} other{# points}}',
    'Upgrade to {edition}' => 'Passer à {edition}',
    'Upgrade to the {edition} edition to unlock this feature.' => 'Passez à l\'édition {edition} pour débloquer cette fonction.',
    'URI Pattern' => 'Motif d\'URI',
    'URL' => 'URL',
    'Use "Not Applicable" when the criterion cannot arise, e.g. Captions when the site has no video.' => 'Utilisez « Non applicable » quand le critère ne peut pas se présenter, p. ex. les sous-titres si le site n’a pas de vidéo.',
    'Use common words. Replace "utilise" with "use", "commence" with "start".' => 'Employez des mots courants. Remplacez « utiliser » par « se servir de », « débuter » par « commencer ».',
    'Use concrete nouns and verbs over nominalisations ("investigation" → "investigate").' => 'Utilisez des noms et des verbes concrets plutôt que des nominalisations (« investigation » → « enquêter »).',
    'Use the derived status ({status})' => 'Utiliser l\'état déduit ({status})',
    'Used to generate alt text suggestions with Claude (Haiku). Get a key at platform.claude.com. You can also reference an environment variable: type $ to see suggestions.' => 'Sert à générer des suggestions de texte alternatif avec Claude (Haiku). Obtenez une clé sur platform.claude.com. Vous pouvez aussi référencer une variable d\'environnement : saisissez $ pour voir les suggestions.',
    'Verification failed.' => 'Échec de la vérification.',
    'Verify API Key' => 'Vérifier la clé API',
    'Verifying…' => 'Vérification…',
    'Version {version}' => 'Version {version}',
    'Very hard to read' => 'Très difficile à lire',
    'Very hard to read, grade {n}:' => 'Très difficile à lire, niveau {n} :',
    'Very short alt' => 'Alt très court',
    'via the Plugin Store' => 'via le Plugin Store',
    'View accessibility reports' => 'Voir les rapports d\'accessibilité',
