    'View report' => 'Voir le rapport',
    'View the full report: {url}' => 'Voir le rapport complet : {url}',
    'View WCAG guidance' => 'Voir les recommandations WCAG',
    'Visual impairment' => 'Déficience visuelle',
    'Visual impairment filters' => 'Filtres de déficience visuelle',
    'Volume' => 'Volume',
    'VPAT' => 'VPAT',
    'VPAT Conformance Reporting' => 'Rapports de conformité VPAT',
    'VPAT export' => 'Export VPAT',
    'VPAT Export Template' => 'Template d\'export VPAT',
    'VPAT® is a registered service mark of the Information Technology Industry Council (ITI).' => 'VPAT® est une marque de service déposée de l’Information Technology Industry Council (ITI).',
    'VPAT®: WCAG 2.2 Level AA Conformance Report' => 'VPAT® : rapport de conformité WCAG 2.2 niveau AA',
    'Warning' => 'Avertissement',
    'Warnings' => 'Avertissements',
    'warnings' => 'avertissements',
    'Was' => 'Était',
    'WCAG' => 'WCAG',
    'WCAG 2.2 Report' => 'Rapport WCAG 2.2',
