    '{n} selected' => '{n} sélectionné(s)',
    '{organisation} is committed to making this website accessible, in accordance with {legislation}.' => '{organisation} s’engage à rendre ce site accessible, conformément à {legislation}.',
    '{organisation} is committed to making this website accessible.' => '{organisation} s’engage à rendre ce site accessible.',
    '{profile}, under {legislation}.' => '{profile}, selon {legislation}.',
    '{profile}. No statutory statement requirement applies, so nothing below is compulsory.' => '{profile}. Aucune obligation légale de déclaration ne s’applique, rien de ce qui suit n’est donc obligatoire.',
    '{total} images scanned' => '{total} images analysées',
